// mirrorListHeader returns the "Listing mirrors on <core>\n" banner that
// `mirror list` prints to stderr, or "" when no banner should be shown.
//
// mirror list is identity-scoped: it shows the mirrors visible from the active
// login's federation, so naming that login server makes a surprising empty
// result legible — e.g. mirrors that live in a different deployment than the
// active context (--cluster is a filter, not a router). The named core is the
// same one coreapi.New dials for the request.
//
// Returns "" when:
//   - json is true — keep machine output clean.
//   - ENTIRE_TOKEN is set — in that mode the request dials the token's own aud
//     (see coreapi.New / clientFromEnvToken), NOT the active context, so
//     ResolveControlPlaneTarget (which ignores the env token) would name a core
//     the request never talks to. A header that contradicts the request is
//     worse than none.
//   - the active context can't be resolved — best-effort, never a hard failure.
func mirrorListHeader(json bool) string {
	if json {
		return ""
	}
	if _, envToken := os.LookupEnv(auth.EnvTokenVar); envToken {
		return ""
	}
	t, err := auth.ResolveControlPlaneTarget()
	if err != nil {
		return ""
	}
	return fmt.Sprintf("Listing mirrors on %s\n", t.CoreURL)
}

