// TestMirrorListHeader covers the `mirror list` stderr banner. The critical
// case is ENTIRE_TOKEN: in that mode the request dials the token's own aud, not
// the active context, so the header must NOT name the active context's core —
// it would contradict where the request actually goes.
//
// Not parallel: drives process-global state (ENTIRE_CONFIG_DIR, ENTIRE_TOKEN,
// the token-store backend).
func TestMirrorListHeader(t *testing.T) {
	const coreURL = "https://ctx-core.example"

	// seedActiveContext writes a resolvable single active context so
	// ResolveControlPlaneTarget succeeds (the header only reads CoreURL, never
	// mints a token, so no keyring entry is required).
	seedActiveContext := func(t *testing.T) {
		t.Helper()
		configDir := t.TempDir()
		t.Setenv("ENTIRE_CONFIG_DIR", configDir)
		restore := tokenstore.UseFileBackendForTesting(filepath.Join(t.TempDir(), "tokens.json"))
		t.Cleanup(restore)
		c := &contexts.Context{Name: "alice@core", CoreURL: coreURL, Handle: "alice", KeychainService: tokenstore.CoreKeyringService(coreURL)}
		if err := contexts.Save(configDir, &contexts.File{CurrentContext: c.Name, Contexts: []*contexts.Context{c}}); err != nil {
			t.Fatalf("write contexts.json: %v", err)
		}
	}

	t.Run("names the active context's core", func(t *testing.T) {
		seedActiveContext(t)
		if got := mirrorListHeader(false); got != "Listing mirrors on "+coreURL+"\n" {
			t.Fatalf("header = %q, want it to name %q", got, coreURL)
		}
	})

	t.Run("suppressed for --json", func(t *testing.T) {
		seedActiveContext(t)
		if got := mirrorListHeader(true); got != "" {
			t.Fatalf("header = %q, want empty for --json", got)
		}
	})

	t.Run("suppressed when ENTIRE_TOKEN is set even with a resolvable context", func(t *testing.T) {
		seedActiveContext(t)
		// A resolvable context is present, so without the env-token guard the
		// header would name coreURL — a core the request never dials in env-token
		// mode. The guard must win.
		t.Setenv(auth.EnvTokenVar, "some-token")
		if got := mirrorListHeader(false); got != "" {
			t.Fatalf("header = %q, want empty when ENTIRE_TOKEN is set", got)
		}
	})

	t.Run("suppressed when no active context (best-effort)", func(t *testing.T) {
		t.Setenv("ENTIRE_CONFIG_DIR", t.TempDir())
		restore := tokenstore.UseFileBackendForTesting(filepath.Join(t.TempDir(), "tokens.json"))
		t.Cleanup(restore)
		if got := mirrorListHeader(false); got != "" {
			t.Fatalf("header = %q, want empty when not logged in", got)
		}
	})
}

